import React, { useState } from 'react';
import LoginScreen from './components/auth/LoginScreen/LoginScreen';
import AppLayout from './components/layout/AppLayout/AppLayout';
import Admin5Dashboard from './pages/admin5/Admin5Dashboard/Admin5Dashboard';

function App() {
  const [userRole, setUserRole] = useState(null);
  const [currentPage, setCurrentPage] = useState('dashboard');

  const loginAs = (role) => {
    setUserRole(role);
    setCurrentPage('dashboard'); // Define a página inicial ao logar
  };

  const logout = () => {
    setUserRole(null);
  };

  const navigate = (page) => {
    setCurrentPage(page);
  };

  // Renderiza o conteúdo da página com base no estado 'currentPage'
  const renderPage = () => {
    switch (currentPage) {
      case 'dashboard':
        // No futuro, podemos ter um dashboard diferente para cada perfil
        if (userRole === 'admin5') {
          return <Admin5Dashboard onNavigate={navigate} />;
        }
        return <h1>Dashboard</h1>; // Placeholder para outros perfis
      // Adicione outros 'cases' para as outras páginas aqui
      // case 'create_admin':
      //   return <CreateAdminPage />;
      default:
        return <h1>Página não encontrada</h1>;
    }
  };

  // Se não houver perfil, mostra o ecrã de login
  if (!userRole) {
    return <LoginScreen loginAs={loginAs} />;
  }

  // Se houver um perfil, mostra o layout principal com a página correta
  return (
    <AppLayout onNavigate={navigate} onLogout={logout} activePage={currentPage}>
      {renderPage()}
    </AppLayout>
  );
}

export default App;
